#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA%d:%s line%d\n",int(e),cudaGetErrorString(e),__LINE__);exit(2);}}while(0)
using B=uint8_t;using U=uint32_t;
std::vector<B>readall(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error(p);size_t n=f.tellg();f.seekg(0);std::vector<B>x(n);f.read((char*)x.data(),n);if(!f)throw std::runtime_error("shortread");return x;}
struct Buf{B*base;size_t n;Buf(size_t size):n(size){C(cudaMalloc(&base,n+32));C(cudaMemset(base,0xa5,n+32));C(cudaMemset(base+16,0,n));}~Buf(){C(cudaFree(base));}template<class T>T*ptr(){return(T*)(base+16);}std::vector<B>all(){std::vector<B>x(n+32);C(cudaMemcpy(x.data(),base,n+32,cudaMemcpyDeviceToHost));return x;}std::vector<B>live(size_t m){if(m>n)throw std::runtime_error("livebounds");std::vector<B>x(m+32);C(cudaMemcpy(x.data(),base,16,cudaMemcpyDeviceToHost));C(cudaMemcpy(x.data()+16,base+16,m,cudaMemcpyDeviceToHost));C(cudaMemcpy(x.data()+16+m,base+16+n,16,cudaMemcpyDeviceToHost));return x;}};
void append(std::vector<B>&a,const std::vector<B>&b){a.insert(a.end(),b.begin(),b.end());}
int main(){auto input=readall("study_input_u32.bin"),pre=readall("oracle_prefix_u8.bin"),out=readall("oracle_output_u8.bin");for(int t=0;t<=5;t++){std::vector<B>actualpre,actualout;std::ifstream cases("cases.txt");U orig,nb,nf,nd;size_t ip=0;double comp=0,decomp=0;while(cases>>orig>>nb>>nf>>nd){size_t padded=nb*2048;Buf in(padded),decoded(padded),fs((nb+1)*4),ds((nb+1)*4),fo((nb+1)*4),doo((nb+1)*4),tf(nb*64),td(padded),pf(nb*64),pd(padded);C(cudaMemcpy(in.ptr<B>(),input.data()+ip,padded,cudaMemcpyHostToDevice));ip+=padded;append(actualpre,in.all());C(cudaDeviceSynchronize());auto a=std::chrono::steady_clock::now();compressKernelI<U><<<nb,128>>>(in.ptr<U>(),nb,fs.ptr<U>(),ds.ptr<U>(),tf.ptr<B>(),td.ptr<B>(),1);void*scratch1=nullptr,*scratch2=nullptr;size_t ns1=0,ns2=0;C(cub::DeviceScan::ExclusiveSum(scratch1,ns1,fs.ptr<U>(),fo.ptr<U>(),nb+1));C(cudaMalloc(&scratch1,ns1));C(cub::DeviceScan::ExclusiveSum(scratch1,ns1,fs.ptr<U>(),fo.ptr<U>(),nb+1));C(cub::DeviceScan::ExclusiveSum(scratch2,ns2,ds.ptr<U>(),doo.ptr<U>(),nb+1));C(cudaMalloc(&scratch2,ns2));C(cub::DeviceScan::ExclusiveSum(scratch2,ns2,ds.ptr<U>(),doo.ptr<U>(),nb+1));compressKernelIII<U><<<nb,128>>>(nb,fo.ptr<U>(),doo.ptr<U>(),tf.ptr<B>(),td.ptr<B>(),pf.ptr<B>(),pd.ptr<B>());C(cudaDeviceSynchronize());C(cudaFree(scratch1));C(cudaFree(scratch2));auto b=std::chrono::steady_clock::now();decompressKernel<U><<<(nb+31)/32,32>>>(decoded.ptr<U>(),nb,fo.ptr<U>(),doo.ptr<U>(),pf.ptr<B>(),pd.ptr<B>());C(cudaDeviceSynchronize());auto c=std::chrono::steady_clock::now();comp+=std::chrono::duration<double>(b-a).count();decomp+=std::chrono::duration<double>(c-b).count();C(cudaGetLastError());append(actualout,decoded.all());append(actualout,fs.all());append(actualout,ds.all());append(actualout,fo.all());append(actualout,doo.all());append(actualout,tf.all());append(actualout,td.all());append(actualout,pf.live(nf));append(actualout,pd.live(nd));}if(ip!=input.size()||actualpre!=pre||actualout!=out){size_t j=0;while(j<out.size()&&j<actualout.size()&&out[j]==actualout[j])j++;fprintf(stderr,"full-byte-check failed prefix%d outputoffset%zu expected%d actual%d sizes%zu/%zu\n",int(actualpre==pre),j,j<out.size()?out[j]:-1,j<actualout.size()?actualout[j]:-1,out.size(),actualout.size());return 3;}if(t){std::string p=std::string(getenv("STUDY_OUTPUT_DIR"))+"/lzss_trial"+std::to_string(t)+".bin";std::ofstream f(p,std::ios::binary);f.write((char*)actualpre.data(),actualpre.size());f.write((char*)actualout.data(),actualout.size());f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"compression_seconds\":%.17g,\"decompression_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"jit_excluded\":true,\"timing_region\":\"sum6cases_source_compression_localmatch_globalexclusive_scans_pack_scratch_and_decompression_completion_excludes_captures\",\"iterations\":6,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%zu,\"byte_order\":\"little\"}}\n",t,comp+decomp,comp,decomp,actualpre.size()+actualout.size(),p.c_str(),actualpre.size()+actualout.size());fflush(stdout);}}}
